    Bug 1962967 - Fix intermittent failure in browser_dragDropFolders.js by waiting for async folder move. r=mkmelin


    The `test_drag_and_drop_single_folder` test occasionally failed with
    `TypeError: can't access property "URI", folder is null` because it
    synchronously attempted to read the moved folder (`folderB`) immediately
    after `endDrag()`.

    Since native drag-and-drop and the subsequent backend folder move are
    asynchronous operations (especially pronounced on macOS), this caused
    a race condition.

    This patch adds a `BrowserTestUtils.waitForCondition` block to safely
    poll the destination folder until `getChildNamed` successfully returns
    the moved folder, ensuring the database operation has completed before
    the test assertions continue.

    Differential Revision: https://phabricator.services.mozilla.com/D295827

diff --git a/mail/base/test/browser/browser_dragDropFolders.js b/mail/base/test/browser/browser_dragDropFolders.js
index 041db7d2da1..ecd6464d9ab 100644
--- a/mail/base/test/browser/browser_dragDropFolders.js
+++ b/mail/base/test/browser/browser_dragDropFolders.js
@@ -123,8 +123,17 @@ add_task(async function test_drag_and_drop_single_folder() {
   await startDrag(folderB, folderC);
   await endDrag(folderC);

-  // folderB should now be a child of folderC.
-  folderB = folderC.getChildNamed("folderB");
+  // The backend folder move is asynchronous. Wait for it to complete
+  // and assign the new folder reference as soon as it succeeds.
+  await BrowserTestUtils.waitForCondition(() => {
+    try {
+      folderB = folderC.getChildNamed("folderB");
+      return !!folderB;
+    } catch (ex) {
+      // getChildNamed throws an XPCOM error if the folder doesn't exist yet.
+      return false;
+    }
+  }, "Wait for folderB to successfully become a child of folderC");

